package gvariant

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const key = "xa.extra-data"

// fixtures returns the names of the cases generated by testdata/gen.py.
func fixtures(t *testing.T) []string {
	t.Helper()
	paths, err := filepath.Glob("testdata/*.stripped.gvariant")
	if err != nil {
		t.Fatal(err)
	}
	var names []string
	for _, p := range paths {
		names = append(names, strings.TrimSuffix(filepath.Base(p), ".stripped.gvariant"))
	}
	if len(names) < 12 {
		t.Fatalf("only %d fixtures; run testdata/gen.sh", len(names))
	}
	return names
}

func read(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// TestRemoveKeyMatchesGLib is the byte-for-byte comparison with GLib: the
// dict without xa.extra-data as GLib serialises it.
func TestRemoveKeyMatchesGLib(t *testing.T) {
	for _, name := range fixtures(t) {
		t.Run(name, func(t *testing.T) {
			in := read(t, name+".gvariant")
			want := read(t, name+".stripped.gvariant")
			out, removed, err := RemoveKey(in, key)
			if err != nil {
				t.Fatal(err)
			}
			if removed != !bytes.Equal(in, want) {
				t.Errorf("removed = %v", removed)
			}
			if !bytes.Equal(out, want) {
				t.Errorf("got %d bytes, GLib %d\n got %x\nwant %x", len(out), len(want), head(out), head(want))
			}
		})
	}
}

// TestRoundTrip re-serialises every fixture unchanged.
func TestRoundTrip(t *testing.T) {
	for _, name := range fixtures(t) {
		for _, file := range []string{name + ".gvariant", name + ".stripped.gvariant"} {
			in := read(t, file)
			entries, err := ParseDict(in)
			if err != nil {
				t.Fatalf("%s: %v", file, err)
			}
			if out := SerializeDict(entries); !bytes.Equal(out, in) {
				t.Errorf("%s: round trip differs", file)
			}
		}
	}
}

func TestParseReal(t *testing.T) {
	entries, err := ParseDict(read(t, "real.gvariant"))
	if err != nil {
		t.Fatal(err)
	}
	var got []string
	for _, e := range entries {
		got = append(got, e.Key+" "+e.Type)
	}
	if want := "xa.extra-data a(ayay),ostree.gpgsigs aay"; strings.Join(got, ",") != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestOffsetSizes(t *testing.T) {
	// The cases are meant to cover these array offset sizes before and
	// after stripping; check that they do.
	for name, want := range map[string][2]int{
		"mixed":         {2, 1},
		"last":          {1, 1},
		"offsets-2":     {2, 2},
		"offsets-4":     {4, 4},
		"shrink-4-to-1": {4, 1},
		"shrink-2-to-1": {2, 1},
	} {
		got := [2]int{offsetSizeFor(len(read(t, name+".gvariant"))), offsetSizeFor(len(read(t, name+".stripped.gvariant")))}
		if got != want {
			t.Errorf("%s: offset sizes %v, want %v", name, got, want)
		}
	}
}

func TestNoKeyReturnsInput(t *testing.T) {
	in := read(t, "no-extra-data.gvariant")
	out, removed, err := RemoveKey(in, key)
	if err != nil || removed || &out[0] != &in[0] {
		t.Errorf("removed %v, err %v", removed, err)
	}
}

func TestDuplicateOtherKeyIsRefused(t *testing.T) {
	entries, err := ParseDict(read(t, "mixed.gvariant"))
	if err != nil {
		t.Fatal(err)
	}
	dup := SerializeDict(append(entries, entries[0]))
	if _, err := ParseDict(dup); err != nil {
		t.Fatalf("valid GVariant: %v", err)
	}
	if _, _, err := RemoveKey(dup, key); err == nil {
		t.Error("a dict with a repeated key was rewritten")
	}
}

// TestNotNormalIsRefused feeds input that GLib would read, but not have
// written, and input that is not a dict at all.
func TestNotNormalIsRefused(t *testing.T) {
	mixed := read(t, "mixed.gvariant")
	entries, err := ParseDict(mixed)
	if err != nil {
		t.Fatal(err)
	}
	set := func(b []byte, i int, v byte) []byte {
		b = bytes.Clone(b)
		b[i] = v
		return b
	}
	// A small array with 2-byte offsets where 1 byte is enough.
	small, err := ParseDict(read(t, "last.gvariant"))
	if err != nil {
		t.Fatal(err)
	}
	var wide []byte
	var ends []int
	for _, e := range small {
		for len(wide)%8 != 0 {
			wide = append(wide, 0)
		}
		wide = append(wide, e.Raw...)
		ends = append(ends, len(wide))
	}
	for _, end := range ends {
		wide = appendOffset(wide, uint64(end), 2)
	}
	if offsetSizeFor(len(wide)) != 1 {
		t.Fatal("test needs a small dict")
	}
	// First entry's key padding: "ostree.gpgsigs\0" is 15 bytes, byte 15 pads.
	badPadding := set(mixed, 15, 1)
	// Between the first and second entry.
	firstEnd := len(entries[0].Raw)
	if firstEnd%8 == 0 {
		t.Fatal("test needs padding after the first entry")
	}
	badArrayPadding := set(mixed, firstEnd, 1)
	// Offsets out of order: swap the first two end offsets.
	os := offsetSizeFor(len(mixed))
	table := len(mixed) - os*len(entries)
	swapped := bytes.Clone(mixed)
	copy(swapped[table:], mixed[table+os:table+2*os])
	copy(swapped[table+os:], mixed[table:table+os])
	// A key with invalid UTF-8.
	badKey := bytes.Clone(mixed)
	copy(badKey[0:], []byte{0xff})
	// A variant whose type string is not a type.
	only := read(t, "only-extra-data.gvariant")
	typeAt := bytes.LastIndex(only, []byte("a(ayay)"))
	badType := set(only, typeAt+1, 'z')
	// "u" with a value of 3 bytes
	wrongSize := wrongSizedVariant(t)

	for name, in := range map[string][]byte{
		"wide offsets":   wide,
		"key padding":    badPadding,
		"array padding":  badArrayPadding,
		"offsets order":  swapped,
		"key utf-8":      badKey,
		"type string":    badType,
		"fixed size":     wrongSize,
		"truncated":      mixed[:len(mixed)-1],
		"truncated half": mixed[:len(mixed)/2],
		"one byte":       {0x00},
		"one byte 0xff":  {0xff},
		"zeros":          make([]byte, 64),
		"text":           []byte("this is not a gvariant\n"),
		"last offset 0":  append(bytes.Clone(mixed[:len(mixed)-1]), 0),
	} {
		_, _, err := RemoveKey(in, key)
		if !errors.Is(err, ErrNotNormal) {
			t.Errorf("%s: err %v, want ErrNotNormal", name, err)
		}
		t.Logf("%s: %v", name, err)
	}
}

func wrongSizedVariant(t *testing.T) []byte {
	// {"k": <uint32 with 3 bytes>}: key "k\0", pad to 8, value, NUL, "u",
	// key end offset.
	raw := []byte{'k', 0, 0, 0, 0, 0, 0, 0, 1, 2, 3, 0, 'u', 2}
	return SerializeDict([]Entry{{Raw: raw}})
}

// FuzzRemoveKey checks that arbitrary input never panics, and that what
// RemoveKey writes is itself in normal form without the key.
func FuzzRemoveKey(f *testing.F) {
	paths, _ := filepath.Glob("testdata/*.gvariant")
	for _, p := range paths {
		if b, err := os.ReadFile(p); err == nil && len(b) < 4096 {
			f.Add(b)
		}
	}
	f.Fuzz(func(t *testing.T, in []byte) {
		out, removed, err := RemoveKey(in, key)
		if err != nil || !removed {
			return
		}
		entries, err := ParseDict(out)
		if err != nil {
			t.Fatalf("output not in normal form: %v", err)
		}
		for _, e := range entries {
			if e.Key == key {
				t.Fatal("key still there")
			}
		}
	})
}

func TestTypes(t *testing.T) {
	for typ, want := range map[string]int{
		"y": 1, "b": 1, "n": 2, "u": 4, "t": 8, "d": 8, "s": 0, "v": 0, "ay": 0,
		"()": 1, "(yu)": 8, "(uy)": 8, "(yy)": 2, "(ty)": 16, "(ys)": 0,
		"{sv}": 0, "{yy}": 2, "a{sv}": 0, "a(ayay)": 0, "mu": 0, "(mu)": 0,
	} {
		got, err := fixedSize(typ)
		if err != nil || got != want {
			t.Errorf("%s: size %d, err %v; want %d", typ, got, err, want)
		}
	}
	for _, typ := range []string{"", "a", "(", "(u", "uu", "r", "*", "?", "{vs}", "{s}", "{sss}", "z", strings.Repeat("a", 200) + "y"} {
		if _, err := fixedSize(typ); err == nil {
			t.Errorf("%q accepted", typ)
		}
	}
}

func head(b []byte) []byte {
	if len(b) > 64 {
		return b[:64]
	}
	return b
}
